#[derive(Default, PartialEq, Debug, Clone)]
pub struct Model {
    pub location: ObjectId,
    pub name: String,
    pub source: Option<String>,
}

impl Model {
    pub fn serialize_to<'a>(&self, builder: &mut flatbuffers::FlatBufferBuilder<'a>) -> flatbuffers::WIPOffset<FbsModel<'a>> {
        use crate::types::generated::model_generated::ModelBuilder as FbsModelBuilder;

        let location_offset = self.location.serialize_to(builder);
        let name_offset = builder.create_string(&self.name);
        let source_offset = self.source.as_ref().map(|s| builder.create_string(s));

        let mut bldr = FbsModelBuilder::new(builder);
        bldr.add_location(location_offset);
        bldr.add_name(name_offset);
        if let Some(offset) = source_offset {
            bldr.add_source(offset);
        }
        bldr.finish()
    }
}

impl From<FbsModel<'_>> for Model {
    fn from(fbs: FbsModel<'_>) -> Self {
        let location = ObjectId::from(fbs.location());
        let name = fbs.name().to_owned();
        let source = fbs.source().map(ToOwned::to_owned);
        Self {
            location,
            name,
            source,
        }
    }
}

impl TryFrom<&[u8]> for Model {
    type Error = flatbuffers::InvalidFlatbuffer;
    fn try_from(bytes: &[u8]) -> Result<Self, Self::Error> {
        let fbs = flatbuffers::size_prefixed_root::<FbsModel>(bytes)?;
        Ok(Self::from(fbs))
    }
}

impl From<Model> for Vec<u8> {
    fn from(obj: Model) -> Self {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = obj.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }
}

